# Function to check if MongoDB is installed
function Test-MongoDBInstalled {
    try {
        $mongodVersion = mongod --version
        return $true
    }
    catch {
        return $false
    }
}

# Function to check if MongoDB service is running
function Test-MongoDBRunning {
    $mongoProcess = Get-Process -Name "mongod" -ErrorAction SilentlyContinue
    return $null -ne $mongoProcess
}

# Function to start MongoDB service
function Start-MongoDBService {
    Write-Host "Starting MongoDB service..."
    try {
        # Try to start MongoDB as a service first
        Start-Service MongoDB -ErrorAction SilentlyContinue
        Start-Sleep -Seconds 2
        if (Test-MongoDBRunning) {
            Write-Host "MongoDB service started successfully"
            return $true
        }
        
        # If service start failed, try to start mongod directly
        Write-Host "Service start failed, trying to start mongod directly..."
        Start-Process mongod -ArgumentList "--dbpath", "C:\data\db" -NoNewWindow
        Start-Sleep -Seconds 2
        if (Test-MongoDBRunning) {
            Write-Host "MongoDB started successfully"
            return $true
        }
        
        return $false
    }
    catch {
        Write-Host "Failed to start MongoDB: $_"
        return $false
    }
}

# Function to check if running as administrator
function Test-Administrator {
    $currentUser = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
    return $currentUser.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

# Main script execution
Write-Host "Checking MongoDB installation..."

if (-not (Test-MongoDBInstalled)) {
    Write-Host "MongoDB is not installed."
    
    # Check if running as administrator
    if (-not (Test-Administrator)) {
        Write-Host "Please run this script as Administrator to install MongoDB."
        Write-Host "Right-click on PowerShell and select 'Run as Administrator'"
        exit 1
    }
    
    Write-Host "Would you like to install MongoDB now? (Y/N)"
    $response = Read-Host
    
    if ($response -eq 'Y' -or $response -eq 'y') {
        Write-Host "Installing MongoDB..."
        
        # Create temp directory for download
        $tempDir = Join-Path $env:TEMP "mongodb-setup"
        if (-not (Test-Path $tempDir)) {
            New-Item -ItemType Directory -Path $tempDir -Force | Out-Null
        }
        
        # Download MongoDB installer
        $installerUrl = "https://fastdl.mongodb.org/windows/mongodb-windows-x86_64-6.0.12-signed.msi"
        $installerPath = Join-Path $tempDir "mongodb-installer.msi"
        
        try {
            Write-Host "Downloading MongoDB installer..."
            Invoke-WebRequest -Uri $installerUrl -OutFile $installerPath
            
            # Install MongoDB
            Write-Host "Running MongoDB installer..."
            Start-Process msiexec.exe -ArgumentList "/i", $installerPath, "/quiet", "/norestart" -Wait
            
            # Clean up
            Remove-Item $installerPath -Force
            
            Write-Host "MongoDB installed successfully!"
        }
        catch {
            Write-Host "Failed to install MongoDB automatically. Please install manually:"
            Write-Host "1. Download MongoDB Community Server from: https://www.mongodb.com/try/download/community"
            Write-Host "2. Run the installer and follow the installation wizard"
            Write-Host "3. Choose 'Complete' installation type"
            Write-Host "4. Install MongoDB Compass (the GUI tool) when prompted"
            Write-Host "5. After installation, run this script again"
            exit 1
        }
    }
    else {
        Write-Host "MongoDB installation skipped. Please install MongoDB manually to run tests."
        exit 1
    }
}

Write-Host "MongoDB is installed"

# Check if MongoDB is running
if (-not (Test-MongoDBRunning)) {
    Write-Host "MongoDB is not running"
    
    # Create data directory if it doesn't exist
    $dataDir = "C:\data\db"
    if (-not (Test-Path $dataDir)) {
        Write-Host "Creating MongoDB data directory at $dataDir"
        try {
            New-Item -ItemType Directory -Path $dataDir -Force | Out-Null
        }
        catch {
            Write-Host "Failed to create data directory. Please create it manually:"
            Write-Host "1. Open PowerShell as Administrator"
            Write-Host "2. Run: New-Item -ItemType Directory -Path C:\data\db -Force"
            exit 1
        }
    }
    
    # Try to start MongoDB
    if (-not (Start-MongoDBService)) {
        Write-Host "Failed to start MongoDB automatically. Please try these steps manually:"
        Write-Host "1. Open a new PowerShell window as Administrator"
        Write-Host "2. Run: Start-Service MongoDB"
        Write-Host "3. If that fails, run: mongod --dbpath C:\data\db"
        exit 1
    }
}

Write-Host "MongoDB is running"
Write-Host "Test database will be created automatically when running tests"
Write-Host "Setup complete! You can now run the tests using: npm run test:run" 